import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="GUÍA NUEVA"; N=7; KW=dict(strip=B)
note=lambda t: f'<div style="font-size:36px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:22px">'+"".join(x)+'</div>'
tag=lambda t,c=B: f'<div style="align-self:flex-start;background:{c};color:#FFF;padding:10px 22px;border-radius:8px;font-size:34px;font-weight:800;letter-spacing:4px">{t}</div>'
P=[
page(1,N,T,f'<div style="font-size:40px;font-weight:800;letter-spacing:6px;color:{B}">GUÍA NUEVA, ¿QUÉ CAMBIA?</div>'+big("SEPSIS 2026",190,nowrap=True)+big(f'LO QUE CAMBIA EN TU <span style="color:{R}">GUARDIA</span>',124)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Surviving Sepsis Campaign 2026: 129 enunciados, 46 nuevos. Estos son los que tocan Urgencias.</div>',cover=True,**KW),
page(2,N,T,tag("NUEVO")+big("PRESIÓN ARTERIAL MEDIA",112)+rows(row("Objetivo inicial","65 mmHg"),row("En ≥ 65 años","60–65 mmHg"))+note("Recomienda no perseguir objetivos más altos de entrada. En mayores, la sugerencia es un rango algo inferior."),**KW),
page(3,N,T,tag("NUEVO")+big("ANTIBIÓTICO ANTES DE LLEGAR",104)+'<div style="font-size:48px;font-weight:800;line-height:1.2">Sugerido en el medio prehospitalario si el shock séptico es probable y el traslado supera 60 minutos</div>'+note("Siempre junto a una herramienta de cribado de sepsis. Certeza de la evidencia: muy baja."),**KW),
page(4,N,T,tag("NUEVO")+big("ANAEROBIOS, SOLO SI TOCA",108)+rows(line("Sin factores de riesgo: empírico sin cobertura específica de anaerobios",True),line("Con cobertura: foco abdominal o ginecológico, infección necrosante de partes blandas, cabeza y cuello, absceso o empiema del sistema nervioso central"))+note("Antifúngicos empíricos: la guía pasa a sugerir no usarlos de rutina."),**KW),
page(5,N,T,tag("CAMBIA",R)+big("FLUIDOS Y ALBÚMINA",120)+rows(line("Cristaloides solos, sin albúmina añadida de rutina",True),line("Balanceados antes que salino 0,9 %: sube la certeza de la evidencia"),line("Tras la reanimación, retirada activa de líquido (diuréticos, depuración)"))+note("La albúmina queda para casos concretos: grandes volúmenes ya infundidos o cirrosis."),**KW),
page(6,N,T,tag("SE MANTIENE","#111111")+big("LO DE SIEMPRE, CON MATICES",104)+rows(line("Antibiótico en 1 h si shock posible o sepsis probable; hasta 3 h si sepsis posible sin shock",True),line("Al menos 30 ml/kg de cristaloide en 3 h si hay hipoperfusión"),line("Noradrenalina primero; corticoide en el shock, ahora con menor certeza"))+note("Betalactámicos en perfusión extendida tras la dosis de carga: pasa a recomendación fuerte."),**KW),
page(7,N,T,ficha_body("SEPSIS 2026","Adulto",[("PAM","Objetivo inicial 65 mmHg; 60–65 en ≥ 65 años",True),("PREHOSPITAL","Antibiótico si shock probable y traslado &gt; 60 min"),("ANAEROBIOS","Solo con foco de riesgo (abdominal, ginecológico, necrosante, cabeza y cuello)"),("FLUIDOS","Cristaloide balanceado, sin albúmina de rutina. ≥ 30 ml/kg en 3 h"),("ANTIBIÓTICO","≤ 1 h (shock posible o sepsis probable). ≤ 3 h (sepsis posible sin shock)"),("VASOPRESOR","Noradrenalina primero, también por vía periférica")],"Prescott HC, et al. Surviving Sepsis Campaign: guías internacionales 2026. Crit Care Med 2026",size=124,fs=31),ficha="01",fam="GUÍA",**KW),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","guia-sepsis-2026")
